```turtle
@prefix holon: <https://example.org/holon#> .
@prefix oe: <https://example.org/openevidence#> .
@prefix oeq: <https://example.org/openevidence/questions/> .
@prefix oegen: <https://example.org/openevidence/generated/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
<https://example.org/openevidence/questions/q_breast_cancer_efficacy> a holon:ClinicalQuestionHolon ;
  oeq:hasFact [
    rdf:subject <https://example.org/openevidence/drugs/tamoxifen> ;
    oe:treats <https://example.org/openevidence/diseases/breast_cancer> ;
    effectiveness "effective"
  ] .
```
